// ***************
// Filename: pcie_tl_ep_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of pcie_tl_ep: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to pcie_tl_ep's logic on named ports, its
//   status comes back on input ports. PCIe transaction-layer endpoint: DMA
//   control, address and length, link status, completer ID, BAR0, TLP
//   counters. Generated by ip/scripts/regmap_gen.py from
//   pcie_tl_ep_regs.json: edit the JSON and regenerate (the IP_VERSION /
//   IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "PCIE" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        RW   [0] DMA enabled, reset 0x0
//     0x14 DMA_ADDR_LO RW   DMA host address [31:0] (a write reloads the
//                       address), reset 0x0
//     0x18 DMA_ADDR_HI RW   DMA host address [63:32] (a write reloads the
//                       address), reset 0x0
//     0x1C DMA_LEN_DW  RW   DMA payload per TLP, DWs, reset 0x8
//     0x20 STATUS      RO   status
//                       [0] MEM_EN: memory space enabled by the host
//                       [1] BUS_MASTER: bus mastering enabled by the host
//                       [2] DMA_BUSY: DMA engine busy
//                       [31:16] SF_LEVEL: words in the DMA source FIFO
//     0x24 CPL_ID      RO   completer ID (bus / device / function)
//     0x28 BAR0        RO   BAR0 as programmed by the host
//     0x2C RX_TLP      RO   TLPs received
//     0x30 MWR         RO   memory writes received
//     0x34 MRD         RO   memory reads received
//     0x38 CFG         RO   configuration requests received
//     0x3C UR          RO   unsupported requests
//     0x40 DMA_TLP     RO   DMA TLPs sent
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-12
module pcie_tl_ep_regs (
  input  logic          aclk,             // clock
  input  logic          aresetn,          // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  input  logic [7:0]    s_axil_awaddr,    // AXI4-Lite
  input  logic          s_axil_awvalid,
  output logic          s_axil_awready,
  input  logic [31:0]   s_axil_wdata,
  input  logic [3:0]    s_axil_wstrb,
  input  logic          s_axil_wvalid,
  output logic          s_axil_wready,
  output logic [1:0]    s_axil_bresp,
  output logic          s_axil_bvalid,
  input  logic          s_axil_bready,
  input  logic [7:0]    s_axil_araddr,
  input  logic          s_axil_arvalid,
  output logic          s_axil_arready,
  output logic [31:0]   s_axil_rdata,
  output logic [1:0]    s_axil_rresp,
  output logic          s_axil_rvalid,
  input  logic          s_axil_rready,
  output logic          ctrl_o,           // CTRL (RW): register value
  output logic          ctrl_wr_o,        // CTRL: one-clock pulse at every software write
  output logic [32-1:0] dma_addr_lo_o,    // DMA_ADDR_LO (RW): register value
  output logic          dma_addr_lo_wr_o, // DMA_ADDR_LO: one-clock pulse at every software write
  output logic [32-1:0] dma_addr_hi_o,    // DMA_ADDR_HI (RW): register value
  output logic          dma_addr_hi_wr_o, // DMA_ADDR_HI: one-clock pulse at every software write
  output logic [10-1:0] dma_len_dw_o,     // DMA_LEN_DW (RW): register value
  output logic          dma_len_dw_wr_o,  // DMA_LEN_DW: one-clock pulse at every software write
  input  logic [32-1:0] status_i,         // STATUS (RO): value read
  input  logic [16-1:0] cpl_id_i,         // CPL_ID (RO): value read
  input  logic [32-1:0] bar0_i,           // BAR0 (RO): value read
  input  logic [32-1:0] rx_tlp_i,         // RX_TLP (RO): value read
  input  logic [32-1:0] mwr_i,            // MWR (RO): value read
  input  logic [32-1:0] mrd_i,            // MRD (RO): value read
  input  logic [32-1:0] cfg_i,            // CFG (RO): value read
  input  logic [32-1:0] ur_i,             // UR (RO): value read
  input  logic [32-1:0] dma_tlp_i         // DMA_TLP (RO): value read
);
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "PCIE";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_DMA_ADDR_LO = 8'h14;
  localparam logic [7:0] A_DMA_ADDR_HI = 8'h18;
  localparam logic [7:0] A_DMA_LEN_DW = 8'h1C;
  localparam logic [7:0] A_STATUS = 8'h20;
  localparam logic [7:0] A_CPL_ID = 8'h24;
  localparam logic [7:0] A_BAR0 = 8'h28;
  localparam logic [7:0] A_RX_TLP = 8'h2C;
  localparam logic [7:0] A_MWR = 8'h30;
  localparam logic [7:0] A_MRD = 8'h34;
  localparam logic [7:0] A_CFG = 8'h38;
  localparam logic [7:0] A_UR = 8'h3C;
  localparam logic [7:0] A_DMA_TLP = 8'h40;
  localparam int MAP_WORDS = 17;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .wr_en_o(wr_en),
    .wr_addr_o(wr_addr),
    .wr_data_o(wr_data),
    .wr_strb_o(wr_strb),
    .wr_err_i(wr_err_q),
    .rd_en_o(rd_en),
    .rd_addr_o(rd_addr),
    .rd_data_i(rd_data),
    .rd_valid_i(1'b1),
    .rd_err_i(1'b0)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] dma_addr_lo_q;
  logic [31:0] dma_addr_hi_q;
  logic [31:0] dma_len_dw_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= 32'h0;
      ctrl_wr_o <= 1'b0;
      dma_addr_lo_q <= 32'h0;
      dma_addr_lo_wr_o <= 1'b0;
      dma_addr_hi_q <= 32'h0;
      dma_addr_hi_wr_o <= 1'b0;
      dma_len_dw_q <= 32'h8;
      dma_len_dw_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_STATUS || wa == A_CPL_ID || wa == A_BAR0 || wa == A_RX_TLP || wa == A_MWR || wa == A_MRD || wa == A_CFG || wa == A_UR || wa == A_DMA_TLP);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        dma_addr_lo_wr_o <= wr_en && wa == A_DMA_ADDR_LO;
        if (wr_en && wa == A_DMA_ADDR_LO) dma_addr_lo_q <= (dma_addr_lo_q & ~wmask) | (wr_data & wmask);
      end
      begin
        dma_addr_hi_wr_o <= wr_en && wa == A_DMA_ADDR_HI;
        if (wr_en && wa == A_DMA_ADDR_HI) dma_addr_hi_q <= (dma_addr_hi_q & ~wmask) | (wr_data & wmask);
      end
      begin
        dma_len_dw_wr_o <= wr_en && wa == A_DMA_LEN_DW;
        if (wr_en && wa == A_DMA_LEN_DW) dma_len_dw_q <= (dma_len_dw_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[1-1:0];
  assign dma_addr_lo_o = dma_addr_lo_q[32-1:0];
  assign dma_addr_hi_o = dma_addr_hi_q[32-1:0];
  assign dma_len_dw_o = dma_len_dw_q[10-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = ctrl_q;
      A_DMA_ADDR_LO: rd_data = dma_addr_lo_q;
      A_DMA_ADDR_HI: rd_data = dma_addr_hi_q;
      A_DMA_LEN_DW: rd_data = dma_len_dw_q;
      A_STATUS: rd_data = 32'(status_i);
      A_CPL_ID: rd_data = 32'(cpl_id_i);
      A_BAR0: rd_data = 32'(bar0_i);
      A_RX_TLP: rd_data = 32'(rx_tlp_i);
      A_MWR: rd_data = 32'(mwr_i);
      A_MRD: rd_data = 32'(mrd_i);
      A_CFG: rd_data = 32'(cfg_i);
      A_UR: rd_data = 32'(ur_i);
      A_DMA_TLP: rd_data = 32'(dma_tlp_i);
      default: begin
      end
    endcase
  end
endmodule
